DELETE FROM dpop_proof_use WHERE rowid IN (SELECT rowid FROM dpop_proof_use WHERE retain_until<unixepoch() ORDER BY retain_until LIMIT 1000);
DELETE FROM auth_request_window WHERE rowid IN (SELECT rowid FROM auth_request_window WHERE window_start<unixepoch()-120 ORDER BY window_start LIMIT 1000);
DELETE FROM assertion_use WHERE rowid IN (SELECT rowid FROM assertion_use WHERE retain_until<unixepoch() ORDER BY retain_until LIMIT 1000);
DELETE FROM client_auth_use WHERE accepted_by IN (SELECT accepted_by FROM client_auth_use WHERE retain_until<unixepoch() ORDER BY retain_until LIMIT 1000);
DELETE FROM registration_transaction WHERE tx_id IN (SELECT tx_id FROM registration_transaction WHERE expires_at<unixepoch()-86400 ORDER BY expires_at LIMIT 1000);
DELETE FROM login_transaction WHERE tx_id IN (SELECT tx_id FROM login_transaction WHERE expires_at<unixepoch()-86400 AND NOT EXISTS(SELECT 1 FROM registration_transaction r WHERE r.tx_id=login_transaction.tx_id) ORDER BY expires_at LIMIT 1000);
DELETE FROM web_login_transaction WHERE tx_id IN (SELECT tx_id FROM web_login_transaction WHERE expires_at<unixepoch()-86400 ORDER BY expires_at LIMIT 1000);
DELETE FROM owner_login_transaction WHERE tx_id IN (SELECT tx_id FROM owner_login_transaction WHERE expires_at<unixepoch()-86400 ORDER BY expires_at LIMIT 1000);
DELETE FROM admin_invitation_transaction WHERE rowid IN (SELECT rowid FROM admin_invitation_transaction WHERE expires_at<unixepoch()-86400 ORDER BY expires_at LIMIT 1000);
DELETE FROM logout_transaction WHERE csrf_hash IN (SELECT csrf_hash FROM logout_transaction WHERE expires_at<unixepoch()-86400 ORDER BY expires_at LIMIT 1000);
DELETE FROM logout_delivery WHERE rowid IN (SELECT d.rowid FROM logout_delivery d JOIN sso_logout_event e ON e.event_id=d.event_id WHERE e.deadline<unixepoch()-7776000 ORDER BY e.deadline LIMIT 1000);
DELETE FROM sso_logout_event WHERE event_id IN (SELECT event_id FROM sso_logout_event WHERE deadline<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM logout_delivery d WHERE d.event_id=sso_logout_event.event_id) ORDER BY deadline LIMIT 1000);
DELETE FROM vault_oauth_token_context WHERE access_hash IN (SELECT vc.access_hash FROM vault_oauth_token_context vc JOIN token_issue ti ON ti.access_hash=vc.access_hash WHERE ti.access_expires_at<unixepoch()-7776000 ORDER BY ti.access_expires_at LIMIT 1000);
DELETE FROM vault_oauth_code_context WHERE code_hash IN (SELECT vc.code_hash FROM vault_oauth_code_context vc JOIN authorization_code ac ON ac.code_hash=vc.code_hash WHERE ac.expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM token_issue ti WHERE ti.code_hash=ac.code_hash AND ti.access_expires_at>=unixepoch()-7776000) ORDER BY ac.expires_at LIMIT 1000);
DELETE FROM token_issue WHERE code_hash IN (SELECT code_hash FROM token_issue WHERE access_expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM vault_oauth_token_context v WHERE v.access_hash=token_issue.access_hash) ORDER BY access_expires_at LIMIT 1000);
DELETE FROM code_context WHERE code_hash IN (SELECT cc.code_hash FROM code_context cc JOIN authorization_code ac ON ac.code_hash=cc.code_hash WHERE ac.expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM token_issue ti WHERE ti.code_hash=ac.code_hash) ORDER BY ac.expires_at LIMIT 1000);
DELETE FROM par_request WHERE request_uri IN (SELECT request_uri FROM par_request WHERE expires_at<=unixepoch() ORDER BY expires_at LIMIT 1000);
DELETE FROM authorization_code WHERE code_hash IN (SELECT code_hash FROM authorization_code WHERE expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM token_issue ti WHERE ti.code_hash=authorization_code.code_hash) AND NOT EXISTS(SELECT 1 FROM code_context cc WHERE cc.code_hash=authorization_code.code_hash) AND NOT EXISTS(SELECT 1 FROM vault_oauth_code_context vc WHERE vc.code_hash=authorization_code.code_hash) ORDER BY expires_at LIMIT 1000);
DELETE FROM client_session WHERE rowid IN (SELECT cs.rowid FROM client_session cs JOIN sso_session ss ON ss.sso_id=cs.sso_id WHERE ss.expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM authorization_code ac WHERE ac.client_id=cs.client_id AND ac.sid=cs.sid) ORDER BY ss.expires_at LIMIT 1000);
DELETE FROM vault_oauth_grant WHERE grant_id IN (SELECT grant_id FROM vault_oauth_grant WHERE expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM vault_oauth_code_context c WHERE c.grant_id=vault_oauth_grant.grant_id) AND NOT EXISTS(SELECT 1 FROM vault_oauth_token_context t WHERE t.grant_id=vault_oauth_grant.grant_id) ORDER BY expires_at LIMIT 1000);
DELETE FROM vault_oauth_consent WHERE tx_id IN (SELECT tx_id FROM vault_oauth_consent WHERE expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM vault_oauth_grant g WHERE g.consent_tx_id=vault_oauth_consent.tx_id) ORDER BY expires_at LIMIT 1000);
DELETE FROM sso_context WHERE sso_id IN (SELECT sx.sso_id FROM sso_context sx JOIN sso_session ss ON ss.sso_id=sx.sso_id WHERE ss.expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM client_session cs WHERE cs.sso_id=ss.sso_id) AND NOT EXISTS(SELECT 1 FROM sso_logout_event e WHERE e.sso_id=ss.sso_id) AND NOT EXISTS(SELECT 1 FROM logout_transaction l WHERE l.sso_id=ss.sso_id) AND NOT EXISTS(SELECT 1 FROM vault_oauth_consent vc WHERE vc.sso_id=ss.sso_id) ORDER BY ss.expires_at LIMIT 1000);
DELETE FROM sso_session WHERE sso_id IN (SELECT sso_id FROM sso_session WHERE expires_at<unixepoch()-7776000 AND NOT EXISTS(SELECT 1 FROM sso_context sx WHERE sx.sso_id=sso_session.sso_id) AND NOT EXISTS(SELECT 1 FROM client_session cs WHERE cs.sso_id=sso_session.sso_id) AND NOT EXISTS(SELECT 1 FROM sso_logout_event e WHERE e.sso_id=sso_session.sso_id) AND NOT EXISTS(SELECT 1 FROM logout_transaction l WHERE l.sso_id=sso_session.sso_id) AND NOT EXISTS(SELECT 1 FROM vault_oauth_consent vc WHERE vc.sso_id=sso_session.sso_id) ORDER BY expires_at LIMIT 1000);
